using Microsoft.AspNetCore.Authorization;
using Microsoft.EntityFrameworkCore;
using PulseWallet.Infrastructure.ExchangeRates;
using PulseWallet.Infrastructure.Identity;
using PulseWallet.Infrastructure.Persistence;

namespace PulseWallet.Api.Extensions;

public static class WebApplicationExtensions
{
    public static WebApplication UseApiDocumentation(this WebApplication app)
    {
        if (!app.Environment.IsDevelopment())
        {
            return app;
        }

        // The OpenAPI document is generated by the built-in Microsoft.AspNetCore.OpenApi (/openapi/v1.json).
        // Swagger UI only displays it, so the SwaggerUI package is enough (no SwaggerGen needed).
        app.MapOpenApi().AllowAnonymous();
        app.UseSwaggerUI(options => options.SwaggerEndpoint("/openapi/v1.json", "PulseWallet API v1")); // UI at /swagger

        return app;
    }

    public static WebApplication MapAuthEndpoints(this WebApplication app)
    {
        // POST /api/auth/register, /login, /refresh, plus password reset and /manage/info.
        // Minimal API endpoints that ship with ASP.NET Core Identity, under the same /api prefix as the controllers.
        IEndpointConventionBuilder identityEndpoints = app.MapGroup("/api/auth")
            .WithTags("Auth")
            .MapIdentityApi<ApplicationUser>();

        // The fallback policy would also lock register, login, refresh and password reset behind sign-in.
        // Those must stay public; /manage/* (account info, 2FA) already requires a signed-in user, so it's left alone.
        // A convention runs for every endpoint MapIdentityApi created, so the decision is made on the route pattern.
        identityEndpoints.Add(endpoint =>
        {
            if (endpoint is RouteEndpointBuilder { RoutePattern.RawText: string pattern }
                && !pattern.Contains("/manage", StringComparison.Ordinal))
            {
                endpoint.Metadata.Add(new AllowAnonymousAttribute());
            }
        });

        return app;
    }

    // Before app.Run, so the server only starts taking requests once the rates are in the cache.
    // If the provider is down this waits for its retries and timeouts (up to about 15 seconds), then starts without the rates.
    public static async Task LoadExchangeRatesAsync(this WebApplication app)
    {
        // The loader is transient (it holds a typed HttpClient) and there's no request yet, so a scope is created for it.
        await using AsyncServiceScope scope = app.Services.CreateAsyncScope();
        ExchangeRateCacheLoader loader = scope.ServiceProvider.GetRequiredService<ExchangeRateCacheLoader>();
        await loader.LoadAsync(app.Lifetime.ApplicationStopping);
    }

    // Development only: a fresh `docker compose up` gets a working database with no manual step.
    // Production never migrates at startup: several instances would race, and the app's database user
    // shouldn't have DDL rights. There, the pipeline applies migrations before the deployment (#11).
    public static async Task ApplyMigrationsInDevelopmentAsync(this WebApplication app)
    {
        if (!app.Environment.IsDevelopment())
        {
            return;
        }

        // The DbContext is scoped and there's no request yet, so a scope is created just for this.
        await using AsyncServiceScope scope = app.Services.CreateAsyncScope();
        PulseWalletDbContext dbContext = scope.ServiceProvider.GetRequiredService<PulseWalletDbContext>();
        await dbContext.Database.MigrateAsync();
    }
}